#include "agent/tool_runtime/progress_protocol.hpp"
namespace agent_framework::tool_runtime {
ProgressDisposition classify_progress(const InvocationEvent&e)noexcept{if(e.event_type=="invocation_heartbeat"&&!e.information_gain)return ProgressDisposition::AggregateEphemeral;if(e.information_gain)return ProgressDisposition::WakeOrchestrator;return e.durability==InvocationEventDurability::Durable?ProgressDisposition::PersistDurable:ProgressDisposition::AggregateEphemeral;}
std::optional<conversation::RuntimeEventEnvelope> project_runtime_event(const LongRunningToolInvocation&v,const InvocationEvent&e,std::string*error){if(e.invocation_id!=v.invocation_id||e.sequence==0||e.event_type.empty()){if(error)*error="invocation event identity mismatch";return{};}conversation::RuntimeEventEnvelope out;out.event_id=v.invocation_id+":"+std::to_string(e.sequence);out.tenant_id=v.metadata.identity.tenant_id;out.conversation_id=v.conversation_id;out.turn_id=v.turn_id;out.run_id=v.metadata.identity.run_id;out.tool_call_id=v.tool_call_id;out.durability=e.durability==InvocationEventDurability::Durable?conversation::EventDurability::Durable:conversation::EventDurability::Ephemeral;out.visibility=conversation::EventVisibility::Operations;out.event_type="tool_"+e.event_type;out.timestamp=e.created_at;out.payload={{"invocation_id",v.invocation_id},{"invocation_sequence",e.sequence},{"invocation_revision",e.invocation_revision},{"fencing_token",e.fencing_token},{"information_gain",e.information_gain},{"event",e.payload}};return out;}
}
